object Solution {
  def kthSmallestPrimeFraction(arr: Array[Int], k: Int): Array[Int] = {
    val n = arr.length

    // Binary search on fraction value between 0 and 1
    var left = 0.0
    var right = 1.0
    var res = Array(0, 1)

    while (right - left > 1e-9) {
      val mid = (left + right) / 2
      // Count how many fractions <= mid, and track the max fraction <= mid
      var count = 0
      var maxNumer = 0
      var maxDenom = 1
      var j = 1

      for (i <- 0 until n - 1) {
        while (j < n && arr(i).toDouble / arr(j) > mid) {
          j += 1
        }
        if (j == n) {
          // no more fractions with denominator >= j
          // so no fractions for this i <= mid
          // continue to next i
        } else {
          count += (n - j)
          // Among fractions arr[i]/arr[j..n-1], arr[i]/arr[j] is the smallest
          // Check if arr[i]/arr[j] > current max fraction <= mid
          if (arr(i) * maxDenom > maxNumer * arr(j)) {
            maxNumer = arr(i)
            maxDenom = arr(j)
          }
        }
      }

      if (count < k) {
        left = mid
      } else {
        right = mid
        res = Array(maxNumer, maxDenom)
      }
    }

    res
  }
}

